1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return no living cells for a single living cell", () => {
6	    expect(nextGeneration([[0, 0]])).toEqual([]);
7	  });
8	  it("should let both cells die when each has only one live neighbor", () => {
9	    expect(
10	      nextGeneration([
11	        [0, 1],
12	        [1, 1],
13	      ]),
14	    ).toEqual([]);
15	  });
16	  it("should keep a live cell with three live neighbors alive", () => {
17	    expect(
18	      nextGeneration([
19	        [0, 0],
20	        [0, 1],
21	        [0, 2],
22	        [1, 1],
23	      ]),
24	    ).toContainEqual([1, 1]);
25	  });
26	  it("should keep a live cell with two live neighbors alive", () => {
27	    expect(
28	      nextGeneration([
29	        [0, 0],
30	        [0, 1],
31	        [0, 2],
32	      ]),
33	    ).toContainEqual([0, 1]);
34	  });
35	  it("should let a live cell with four live neighbors die", () => {
36	    expect(
37	      nextGeneration([
38	        [0, 0],
39	        [1, 0],
40	        [2, 0],
41	        [1, 1],
42	        [1, 2],
43	      ]),
44	    ).not.toContainEqual([1, 1]);
45	  });
46	  it.todo("should bring a dead cell with exactly three live neighbors to life");
47	  it.todo("should keep a block unchanged");
48	  it.todo("should turn a vertical blinker into a horizontal blinker");
49	  it.todo("should return the blinker to its original state after two generations");
50	  it.todo("should compute the next generation for cells at negative coordinates");
51	});
52

1	export type Cell = [number, number];
2	
3	const isNeighbor = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
4	  Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1 && !(x1 === x2 && y1 === y2);
5	
6	const countLiveNeighbors = (cell: Cell, livingCells: Cell[]): number =>
7	  livingCells.filter((other) => isNeighbor(cell, other)).length;
8	
9	const survives = (cell: Cell, livingCells: Cell[]): boolean => {
10	  const liveNeighbors = countLiveNeighbors(cell, livingCells);
11	  return liveNeighbors === 2 || liveNeighbors === 3;
12	};
13	
14	export const nextGeneration = (livingCells: Cell[]): Cell[] =>
15	  livingCells.filter((cell) => survives(cell, livingCells));
